    ovOver: document.getElementById('ovOver'),
    btnStart: document.getElementById('btnStart'),
    btnResume: document.getElementById('btnResume'),
    btnRestart: document.getElementById('btnRestart'),
    btnPlay: document.getElementById('btnPlay'),
    playLabel: document.getElementById('playLabel'),
    btnPause: document.getElementById('btnPause'),
    btnReset: document.getElementById('btnReset'),
    btnDpadCenter: document.getElementById('btnDpadCenter'),
    dpad: document.getElementById('dpad')
  };

  // ---------- canvas sizing ----------
  let cell = 20, dpr = 1;
  function resize(){
    const rect = canvas.getBoundingClientRect();
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    const size = Math.max(1, Math.floor(rect.width));
    canvas.width = size * dpr;
    canvas.height = size * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    cell = size / COLS;
    draw();
  }
  window.addEventListener('resize', resize);

  // ---------- helpers ----------
  function randInt(n){ return Math.floor(Math.random() * n); }

  function freeCells(){
    const occ = new Set(snake.map(s => s.x + ',' + s.y));
    const free = [];
    for(let y=0;y<ROWS;y++) for(let x=0;x<COLS;x++){
      if(!occ.has(x+','+y)) free.push({x,y});
    }
    return free;
  }

  function spawnFood(){
    const free = freeCells();
    if(free.length === 0){ win(); return; }
    food = free[randInt(free.length)];
    foodPulse = 0;
  }

  // ---------- game flow ----------
  function reset(){
    const cx = Math.floor(COLS/2), cy = Math.floor(ROWS/2);
    snake = [{x:cx-1,y:cy},{x:cx,y:cy},{x:cx+1,y:cy}];
    dir = {x:1,y:0};
    nextDir = {x:1,y:0};
    score = 0; level = 1; interval = BASE_INTERVAL;
    particles = [];
    spawnFood();
    updateHUD();
  }

  function start(){
    if(state === 'playing') return;
    if(state === 'over' || state === 'ready') reset();
    state = 'playing';
    acc = 0; last = performance.now();
    hideOverlays();
    setPlayLabel('暂停');
    if(!rafId) rafId = requestAnimationFrame(loop);
  }

  function pause(){
    if(state !== 'playing') return;
    state = 'paused';
    show(el.ovPause);
    setPlayLabel('继续');
  }

  function resume(){
    if(state !== 'paused') return;
    state = 'playing';
    last = performance.now();
    hideOverlays();
    setPlayLabel('暂停');
  }

  function togglePlay(){
    if(state === 'playing') pause();
    else if(state === 'paused') resume();
    else start();
  }

  function restart(){
    reset();
    state = 'playing';
    acc = 0; last = performance.now();
    hideOverlays();
    setPlayLabel('暂停');
    if(!rafId) rafId = requestAnimationFrame(loop);
  }

  function gameOver(){
    state = 'over';
    if(score > best){
      best = score;
      try{ localStorage.setItem('snake_best', best); }catch(e){}
      el.overMsg.textContent = '🎉 新纪录！本局得分';
    }else{
      el.overMsg.textContent = '本局得分';
    }
    el.finalScore.textContent = score;
    updateHUD();
    show(el.ovOver);
    setPlayLabel('开始');
  }

  function win(){
    state = 'over';
    if(score > best){ best = score; try{ localStorage.setItem('snake_best', best); }catch(e){} }
    el.finalScore.textContent = score;
    el.overMsg.textContent = '🏆 你填满了整个棋盘！';
    updateHUD();
    show(el.ovOver);
    setPlayLabel('开始');
  }

  // ---------- step ----------
  function step(){
    dir = nextDir;
    const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

    // wall collision
    if(head.x < 0 || head.x >= COLS || head.y < 0 || head.y >= ROWS){
      gameOver(); return;
    }
    // self collision (tail cell will move unless we eat)
    const willEat = (head.x === food.x && head.y === food.y);
    const body = willEat ? snake : snake.slice(0, -1);
    for(const s of body){
      if(s.x === head.x && s.y === head.y){ gameOver(); return; }
    }

    snake.unshift(head);

    if(willEat){
      score += POINTS;
      level = 1 + Math.floor(score / 50);
      interval = Math.max(MIN_INTERVAL, BASE_INTERVAL - (level - 1) * SPEED_STEP);
      burst(head.x, head.y);
      spawnFood();
      popScore();
      updateHUD();
    }else{
      snake.pop();
    }
  }

  // ---------- loop ----------
  function loop(now){
    rafId = requestAnimationFrame(loop);
    const dt = now - last;
    last = now;
    foodPulse += dt;

    if(state === 'playing'){
      acc += dt;
      let guard = 0;
      while(acc >= interval && state === 'playing' && guard < 5){
        step();
        acc -= interval;
        guard++;
      }
    }
    updateParticles(dt);
    draw();
  }

  // ---------- particles ----------
  function burst(cx, cy){
    const px = (cx + 0.5) * cell, py = (cy + 0.5) * cell;
    for(let i=0;i<16;i++){
      const a = Math.random() * Math.PI * 2;
      const sp = 0.05 + Math.random() * 0.18;
      particles.push({
        x: px, y: py,
        vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
        life: 1, size: 2 + Math.random() * 3,
        hue: Math.random() < 0.5 ? '57,224,127' : '255,207,92'
      });
    }
  }
  function updateParticles(dt){
    const f = dt / 16.67;
    for(let i=particles.length-1;i>=0;i--){
      const p = particles[i];
      p.x += p.vx * cell * f;
      p.y += p.vy * cell * f;
      p.vy += 0.0006 * cell * f;
      p.life -= 0.02 * f;
      if(p.life <= 0) particles.splice(i,1);
    }
  }

  // ---------- drawing ----------
  function roundRect(x, y, w, h, r){
    r = Math.min(r, w/2, h/2);
    ctx.beginPath();
    ctx.moveTo(x+r, y);
    ctx.arcTo(x+w, y, x+w, y+h, r);
    ctx.arcTo(x+w, y+h, x, y+h, r);
    ctx.arcTo(x, y+h, x, y, r);
    ctx.arcTo(x, y, x+w, y, r);
    ctx.closePath();
  }

  function draw(){
    const W = canvas.width / dpr, H = canvas.height / dpr;
    ctx.clearRect(0, 0, W, H);

    // checkerboard
    for(let y=0;y<ROWS;y++){
      for(let x=0;x<COLS;x++){
        if((x+y) % 2 === 0){
          ctx.fillStyle = 'rgba(120,255,190,0.028)';
          ctx.fillRect(x*cell, y*cell, cell, cell);
        }
      }
    }

    // food
    if(food){
      const fx = (food.x + 0.5) * cell, fy = (food.y + 0.5) * cell;
      const pulse = 1 + Math.sin(foodPulse / 220) * 0.12;
      const r = cell * 0.34 * pulse;
      // glow
      const g = ctx.createRadialGradient(fx, fy, 0, fx, fy, r*2.4);
      g.addColorStop(0, 'rgba(255,207,92,0.55)');
      g.addColorStop(1, 'rgba(255,207,92,0)');
      ctx.fillStyle = g;
      ctx.beginPath(); ctx.arc(fx, fy, r*2.4, 0, Math.PI*2); ctx.fill();
      // body
      const fg = ctx.createRadialGradient(fx - r*0.3, fy - r*0.3, r*0.1, fx, fy, r);
      fg.addColorStop(0, '#fff2c9');
      fg.addColorStop(0.5, '#ffcf5c');
      fg.addColorStop(1, '#f59e0b');
      ctx.fillStyle = fg;
      ctx.beginPath(); ctx.arc(fx, fy, r, 0, Math.PI*2); ctx.fill();
      // leaf
      ctx.fillStyle = '#39e07f';
      ctx.beginPath();
      ctx.ellipse(fx + r*0.35, fy - r*0.95, r*0.32, r*0.18, -0.6, 0, Math.PI*2);
      ctx.fill();
    }

    // snake
    const n = snake.length;
    for(let i=n-1;i>=0;i--){
      const s = snake[i];
      const t = n > 1 ? i/(n-1) : 0;
      const pad = cell * (0.08 + t*0.06);
      const x = s.x*cell + pad, y = s.y*cell + pad;
      const w = cell - pad*2, h = cell - pad*2;
      const rad = cell * 0.32;

      // color gradient head->tail
      const light = 1 - t*0.55;
      const cr = Math.round(125 * light + 18 * (1-light));
      const cg = Math.round(255 * light + 181 * (1-light));
      const cb = Math.round(176 * light + 106 * (1-light));
      ctx.fillStyle = 'rgb(' + cr + ',' + cg + ',' + cb + ')';

      // glow on head
      if(i === 0){
        ctx.save();
        ctx.shadowColor = 'rgba(125,255,176,0.9)';
        ctx.shadowBlur = cell * 0.7;
        roundRect(x, y, w, h, rad);
        ctx.fill();
        ctx.restore();
      }else{
        roundRect(x, y, w, h, rad);
        ctx.fill();
      }
    }

    // eyes on head
    const head = snake[0];
    const hx = (head.x + 0.5) * cell, hy = (head.y + 0.5) * cell;
    const eo = cell * 0.16;
    const ex = dir.y !== 0 ? eo : 0;
    const ey = dir.x !== 0 ? eo : 0;
    const fwd = cell * 0.14;
    const eyeR = cell * 0.11;
    ctx.fillStyle = '#04140c';
    ctx.beginPath(); ctx.arc(hx + dir.x*fwd + ex, hy + dir.y*fwd + ey, eyeR, 0, Math.PI*2); ctx.fill();
    ctx.beginPath(); ctx.arc(hx - dir.y*eo + dir.x*fwd, hy + dir.x*eo + dir.y*fwd, eyeR, 0, Math.PI*2); ctx.fill();
    // pupils
    ctx.fillStyle = '#7dffb0';
    ctx.beginPath(); ctx.arc(hx + dir.x*fwd + ex + dir.x*2, hy + dir.y*fwd + ey + dir.y*2, eyeR*0.4, 0, Math.PI*2); ctx.fill();
    ctx.beginPath(); ctx.arc(hx - dir.y*eo + dir.x*fwd + dir.x*2, hy + dir.x*eo + dir.y*fwd + dir.y*2, eyeR*0.4, 0, Math.PI*2); ctx.fill();

    // particles
    for(const p of particles){
      ctx.fillStyle = 'rgba(' + p.hue + ',' + Math.max(0, p.life) + ')';
      ctx.beginPath(); ctx.arc(p.x, p.y, p.size * p.life, 0, Math.PI*2); ctx.fill();
    }
  }

  // ---------- HUD ----------
  function updateHUD(){
    el.score.textContent = score;
    el.best.textContent = best;
    el.bestTop.textContent = best;
    el.length.textContent = snake ? snake.length : 3;
    el.speedLvl.textContent = 'Lv ' + level;
    const pct = Math.min(100, ((BASE_INTERVAL - interval) / (BASE_INTERVAL - MIN_INTERVAL)) * 100);
    el.speedBar.style.width = Math.max(6, pct) + '%';
  }
  function popScore(){
    el.score.classList.remove('pop');
    void el.score.offsetWidth;
    el.score.classList.add('pop');
  }
  function setPlayLabel(t){ el.playLabel.textContent = t; }

  // ---------- overlays ----------
  function show(o){ o.classList.remove('hidden'); }
  function hideOverlays(){
    el.ovStart.classList.add('hidden');
    el.ovPause.classList.add('hidden');
    el.ovOver.classList.add('hidden');
  }

  // ---------- input ----------
  function setDir(nx, ny){
    if(state !== 'playing') return;
    if(nx === -dir.x && ny === -dir.y) return; // no reverse
    nextDir = {x:nx, y:ny};
  }

  const keyMap = {
    ArrowUp:[0,-1], ArrowDown:[0,1], ArrowLeft:[-1,0], ArrowRight:[1,0],
    w:[0,-1], s:[0,1], a:[-1,0], d:[1,0],
    W:[0,-1], S:[0,1], A:[-1,0], D:[1,0]
  };

  window.addEventListener('keydown', function(e){
    const k = e.key;
    if(k === ' ' || k === 'Spacebar'){
      e.preventDefault();
      togglePlay();
      return;
    }
    if(k === 'r' || k === 'R'){
      e.preventDefault();
      restart();
      return;
    }
    if(k === 'p' || k === 'P'){
      e.preventDefault();
      if(state === 'playing') pause(); else if(state === 'paused') resume();
      return;
    }
    if(keyMap[k]){
      e.preventDefault();
      const [x,y] = keyMap[k];
      if(state === 'ready' || state === 'over') start();
      setDir(x, y);
    }
  });

  // buttons
  el.btnStart.addEventListener('click', start);
  el.btnResume.addEventListener('click', resume);
  el.btnRestart.addEventListener('click', restart);
  el.btnPlay.addEventListener('click', togglePlay);
  el.btnPause.addEventListener('click', function(){
    if(state === 'playing') pause(); else if(state === 'paused') resume();
  });
  el.btnReset.addEventListener('click', restart);
  el.btnDpadCenter.addEventListener('click', togglePlay);

  // d-pad
  const dirMap = { up:[0,-1], down:[0,1], left:[-1,0], right:[1,0] };
  el.dpad.querySelectorAll('button[data-dir]').forEach(function(b){
    const handler = function(e){
      e.preventDefault();
      const [x,y] = dirMap[b.dataset.dir];
      if(state === 'ready' || state === 'over') start();
      setDir(x, y);
    };
    b.addEventListener('pointerdown', handler);
    b.addEventListener('click', function(e){ e.preventDefault(); });
  });

  // swipe on board
  let touchStart = null;
  const boardEl = canvas;
  boardEl.addEventListener('touchstart', function(e){
    if(e.touches.length === 1){
      touchStart = { x: e.touches[0].clientX, y: e.touches[0].clientY };
    }
  }, {passive:true});
  boardEl.addEventListener('touchend', function(e){
    if(!touchStart) return;
    const t = e.changedTouches[0];
    const dx = t.clientX - touchStart.x;
    const dy = t.clientY - touchStart.y;
    touchStart = null;
    if(Math.abs(dx) < 24 && Math.abs(dy) < 24) return;
    if(Math.abs(dx) > Math.abs(dy)){
      if(state === 'ready' || state === 'over') start();
      setDir(dx > 0 ? 1 : -1, 0);
    }else{
      if(state === 'ready' || state === 'over') start();
      setDir(0, dy > 0 ? 1 : -1);
    }
  }, {passive:true});

  // ---------- init ----------
  try{ best = parseInt(localStorage.getItem('snake_best') || '0', 10) || 0; }catch(e){ best = 0; }
  reset();
  resize();
  updateHUD();
  rafId = requestAnimationFrame(loop);

})();
</script>
</body>
</html>
